insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-pharmacognosy-note-101','Pharmacy','Diploma in Pharmacy','note','free',301,'{"title":"Introduction, Scope and Classification of Pharmacognosy","english":"Pharmacognosy is the study of crude drugs obtained from natural sources such as plants, animals, minerals and microorganisms. It covers identification, cultivation, collection, processing, evaluation, storage, active constituents and uses. Crude drugs may be classified by source, taxonomy, morphology, chemical constituents or therapeutic use. Organized drugs retain cellular structure (for example leaves, roots and bark); unorganized drugs are materials such as gums, resins, latexes and fixed oils.","nepali":"Pharmacognosy भनेको वनस्पति, जनावर, खनिज र सूक्ष्मजीवजस्ता प्राकृतिक स्रोतबाट प्राप्त crude drugs को अध्ययन हो। यसमा पहिचान, खेती, संकलन, प्रशोधन, मूल्याङ्कन, भण्डारण, सक्रिय तत्व र उपयोग समेटिन्छन्। Crude drugs लाई स्रोत, taxonomy, morphology, chemical constituents वा therapeutic use का आधारमा वर्गीकरण गर्न सकिन्छ। Organized drugs मा पात, जरा र बोक्राजस्ता कोशिकीय संरचना रहन्छ; unorganized drugs मा gum, resin, latex र fixed oil जस्ता पदार्थ पर्छन्।"}'::jsonb,true),
('dph-pharmacognosy-note-102','Pharmacy','Diploma in Pharmacy','note','free',302,'{"title":"Cultivation, Collection, Drying and Storage of Crude Drugs","english":"Medicinal plants require suitable climate, soil, water, nutrients and cultivation practices. Collection time and plant part matter because active constituents vary with season, maturity and growth stage. Drugs should be collected from correctly identified, healthy plants, cleaned and dried using a method that limits heat, light, moisture and contamination. Store dried crude drugs in clean, labelled, suitable containers protected from insects, rodents, excess humidity and direct sunlight; follow the relevant monograph for specific requirements.","nepali":"औषधीय वनस्पतिका लागि उपयुक्त हावापानी, माटो, पानी, पोषक तत्व र खेती विधि आवश्यक हुन्छ। सक्रिय तत्व मौसम, परिपक्वता र वृद्धि अवस्थाअनुसार फरक हुन सक्ने भएकाले संकलनको समय र संकलन गरिने भाग महत्त्वपूर्ण हुन्छ। सही पहिचान भएको स्वस्थ बिरुवाबाट संकलन गरी सफा गर्नुपर्छ र ताप, प्रकाश, चिस्यान तथा contamination कम हुने गरी सुकाउनुपर्छ। सुकाइएको crude drug लाई सफा, label गरिएको उपयुक्त भाँडोमा कीरा, मुसा, बढी चिस्यान र प्रत्यक्ष घामबाट जोगाएर राख्नुपर्छ; विशेष नियमका लागि सम्बन्धित monograph पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-pharmacognosy-note-103','Pharmacy','Diploma in Pharmacy','note','free',303,'{"title":"Plant Structure, Morphology and Microscopy","english":"Correct identification of a medicinal plant uses macroscopic characters such as shape, size, colour, odour, taste and surface features, together with microscopic characters. Important plant organs include root, stem, leaf, flower, fruit, seed, bark and rhizome. Plant cells contain structures such as the cell wall, nucleus, vacuole and plastids; tissues include epidermal, ground and vascular tissues. Microscopy can reveal diagnostic features such as stomata, trichomes, vessels, fibres, starch grains and calcium oxalate crystals.","nepali":"औषधीय वनस्पतिको सही पहिचानका लागि आकार, लम्बाइ, रंग, गन्ध, स्वाद र सतहजस्ता macroscopic विशेषतासँगै microscopic विशेषता पनि हेरिन्छ। मुख्य अंगमा root, stem, leaf, flower, fruit, seed, bark र rhizome पर्छन्। Plant cell मा cell wall, nucleus, vacuole र plastids जस्ता संरचना हुन्छन्; tissue मा epidermal, ground र vascular tissue पर्छन्। Microscope बाट stomata, trichomes, vessels, fibres, starch grains र calcium oxalate crystals जस्ता पहिचानका संकेत देख्न सकिन्छ।"}'::jsonb,true),
('dph-pharmacognosy-note-104','Pharmacy','Diploma in Pharmacy','note','free',304,'{"title":"Quality Control, Evaluation and Adulteration of Crude Drugs","english":"Evaluation of crude drugs includes organoleptic and macroscopic examination, microscopy, physical tests, chemical tests and, where appropriate, biological assays. Quality assessment checks identity, purity, strength and contamination. Adulteration may involve substitution with another species, addition of exhausted material, foreign matter or artificial colouring. Good practice includes authenticated reference material, representative sampling, suitable packaging, documented storage and testing against the applicable pharmacopoeial or WHO guidance. Do not identify a drug by taste-testing unknown material.","nepali":"Crude drug को मूल्याङ्कनमा organoleptic तथा macroscopic परीक्षण, microscopy, physical test, chemical test र आवश्यकताअनुसार biological assay पर्छन्। Quality assessment ले पहिचान, शुद्धता, potency र contamination जाँच्छ। Adulteration मा अर्को species ले साट्नु, सक्रिय तत्व निकालिसकेको पदार्थ मिसाउनु, बाहिरी पदार्थ वा कृत्रिम रंग थप्नु पर्न सक्छ। सही अभ्यासमा प्रमाणित reference material, representative sampling, उपयुक्त packaging, अभिलेखसहितको storage र लागू pharmacopoeia वा WHO guidance अनुसार परीक्षण पर्छ। अज्ञात पदार्थको स्वाद चाखेर पहिचान गर्नु हुँदैन।"}'::json,true),
('dph-pharmacognosy-note-105','Pharmacy','Diploma in Pharmacy','note','free',305,'{"title":"Major Phytochemicals and Important Natural Drugs","english":"Important phytochemical groups include alkaloids, glycosides, tannins, phenolic compounds, flavonoids, volatile oils, resins and terpenoids. Examples commonly taught in pharmacognosy include senna leaf/pod containing anthraquinone glycosides, clove flower bud containing eugenol-rich volatile oil, cinchona bark containing quinoline alkaloids, ginger rhizome containing gingerols and digitalis leaf containing cardiac glycosides. Natural origin does not guarantee safety: identity, dose, interactions, contraindications and quality must be assessed, and crude drugs should not be self-prescribed.","nepali":"मुख्य phytochemical समूहमा alkaloids, glycosides, tannins, phenolic compounds, flavonoids, volatile oils, resins र terpenoids पर्छन्। Pharmacognosy मा पढाइने उदाहरणमा anthraquinone glycosides भएको senna leaf/pod, eugenol-rich volatile oil भएको clove flower bud, quinoline alkaloids भएको cinchona bark, gingerols भएको ginger rhizome र cardiac glycosides भएको digitalis leaf पर्छन्। प्राकृतिक स्रोतबाट आएको भन्दैमा पदार्थ सधैँ सुरक्षित हुन्छ भन्ने होइन; पहिचान, मात्रा, औषधिसँगको interaction, contraindication र गुणस्तर जाँच्नुपर्छ। Crude drug आफैँले उपचारका लागि प्रयोग गर्नु हुँदैन।"}'::json,true),
('dph-pharmacognosy-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',301,'{"question":"Pharmacognosy primarily deals with the study of:","translation":"Pharmacognosy मुख्य रूपमा केको अध्ययन हो?","options":["Crude drugs from natural sources","Only synthetic polymers","Only hospital accounts","Only surgical instruments"],"correctIndex":0,"explanation":"Pharmacognosy studies crude drugs and natural products from plant, animal, mineral and microbial sources.","explanationNe":"Pharmacognosy ले वनस्पति, जनावर, खनिज र सूक्ष्मजीव स्रोतका crude drugs तथा natural products को अध्ययन गर्छ।"}'::json,true),
('dph-pharmacognosy-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',302,'{"question":"Which is an example of an unorganized crude drug?","translation":"तलका मध्ये unorganized crude drug को उदाहरण कुन हो?","options":["Leaf","Root","Gum","Bark"],"correctIndex":2,"explanation":"Gum is an exudate without the organized cellular structure of a plant organ.","explanationNe":"Gum बिरुवाको अंगजस्तो व्यवस्थित cellular structure नभएको exudate हो।"}'::json,true),
('dph-pharmacognosy-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',303,'{"question":"Which factor is especially important when deciding the collection time of a medicinal plant?","translation":"औषधीय बिरुवा संकलन गर्ने समय छान्दा कुन कुरा विशेष महत्त्वपूर्ण हुन्छ?","options":["Active constituent content and maturity","Colour of the collection basket","Distance from the market only","Name of the collector"],"correctIndex":0,"explanation":"Active constituents can vary with season and stage of plant growth.","explanationNe":"सक्रिय तत्व मौसम र बिरुवाको वृद्धि/परिपक्वता अवस्थाअनुसार फरक हुन सक्छ।"}'::json,true),
('dph-pharmacognosy-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',304,'{"question":"Which method is used to examine stomata and starch grains in a crude drug?","translation":"Crude drug मा stomata र starch grains जाँच्न कुन विधि प्रयोग हुन्छ?","options":["Microscopy","Titration only","Distillation only","Weighing only"],"correctIndex":0,"explanation":"Microscopy reveals diagnostic cellular and tissue structures.","explanationNe":"Microscopy ले पहिचानका लागि उपयोगी cellular र tissue संरचना देखाउँछ।"}'::json,true),
('dph-pharmacognosy-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',305,'{"question":"Senna is well known for containing which group of active constituents?","translation":"Senna मा कुन समूहका सक्रिय तत्व पाइन्छन्?","options":["Anthraquinone glycosides","Cardiac peptides","Penicillin antibiotics","Mineral silicates"],"correctIndex":0,"explanation":"Senna leaf and pod contain anthraquinone glycosides, including sennosides.","explanationNe":"Senna को पात र फलमा sennosides सहित anthraquinone glycosides पाइन्छन्।"}'::json,true),
('dph-pharmacognosy-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',306,'{"question":"The principal characteristic volatile-oil constituent of clove is:","translation":"Clove को प्रमुख volatile-oil constituent कुन हो?","options":["Eugenol","Quinine","Sennoside","Digoxin"],"correctIndex":0,"explanation":"Clove flower buds contain volatile oil rich in eugenol.","explanationNe":"Clove को flower bud मा eugenol धेरै भएको volatile oil पाइन्छ।"}'::json,true),
('dph-pharmacognosy-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',307,'{"question":"Cinchona bark is a known source of:","translation":"Cinchona bark कुन पदार्थको स्रोतका रूपमा चिनिन्छ?","options":["Quinine alkaloid","Gingerol","Eugenol","Starch"],"correctIndex":0,"explanation":"Cinchona bark contains quinoline alkaloids, including quinine.","explanationNe":"Cinchona bark मा quinine लगायत quinoline alkaloids पाइन्छन्।"}'::json,true),
('dph-pharmacognosy-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',308,'{"question":"Which practice helps prevent deterioration of stored crude drugs?","translation":"भण्डारण गरिएका crude drugs बिग्रन नदिन कुन अभ्यास उपयोगी हुन्छ?","options":["Protect from moisture, pests and direct sunlight","Store wet material in open sacks","Mix old and new stock without labels","Keep beside chemicals with strong odour"],"correctIndex":0,"explanation":"Suitable dry, clean, labelled storage protects crude drugs from moisture, pests and light.","explanationNe":"सुक्खा, सफा र label गरिएको उपयुक्त भण्डारणले चिस्यान, कीरा र प्रकाशबाट crude drug जोगाउँछ।"}'::json,true),
('dph-pharmacognosy-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',309,'{"question":"Which of the following is a common form of adulteration?","translation":"तलका मध्ये adulteration को सामान्य रूप कुन हो?","options":["Substitution with a different species","Correct botanical authentication","Proper drying","Accurate labelling"],"correctIndex":0,"explanation":"Replacing the genuine crude drug with a different species is a form of adulteration.","explanationNe":"वास्तविक crude drug को सट्टा अर्को species राख्नु adulteration हो।"}'::json,true),
('dph-pharmacognosy-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',310,'{"question":"Ginger is commonly obtained from which plant part?","translation":"Ginger सामान्यतया बिरुवाको कुन भागबाट प्राप्त हुन्छ?","options":["Rhizome","Flower","Seed","Bark"],"correctIndex":0,"explanation":"The medicinal ginger material is the rhizome, an underground modified stem.","explanationNe":"औषधीय ginger rhizome हो, जुन जमिनमुनि हुने रूपान्तरित stem हो।"}'::json,true),
('dph-pharmacognosy-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',301,'{"question":"Which statement best describes organized crude drugs?","translation":"Organized crude drug लाई कुन भनाइले सही वर्णन गर्छ?","options":["They retain recognizable plant cellular structure","They are always purified chemicals","They contain no plant tissue","They are only mineral products"],"correctIndex":0,"explanation":"Organized drugs are recognizable plant or animal parts with cellular organization, such as leaves, roots and bark.","explanationNe":"Organized drug मा पात, जरा र बोक्राजस्ता पहिचान गर्न सकिने कोशिकीय संरचना हुन्छ।"}'::json,true),
('dph-pharmacognosy-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',302,'{"question":"Which is the most appropriate first step before collecting a medicinal plant for crude-drug preparation?","translation":"Crude drug बनाउन औषधीय बिरुवा संकलन गर्नुअघि सबैभन्दा उपयुक्त पहिलो कदम कुन हो?","options":["Correctly identify and authenticate the plant","Taste an unknown plant","Mix it with another species","Dry it without checking its condition"],"correctIndex":0,"explanation":"Correct identification prevents substitution, contamination and unsafe use.","explanationNe":"सही पहिचानले गलत species, contamination र असुरक्षित प्रयोगबाट बचाउँछ।"}'::json,true),
('dph-pharmacognosy-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',303,'{"question":"Which evaluation method is best suited to identify diagnostic tissue features in powdered leaf material?","translation":"Powdered leaf material मा diagnostic tissue features पहिचान गर्न कुन मूल्याङ्कन विधि उपयुक्त हुन्छ?","options":["Microscopic evaluation","Only market-price comparison","Only package-weight check","Patient interview"],"correctIndex":0,"explanation":"Microscopic evaluation can identify features such as stomata, trichomes and calcium oxalate crystals.","explanationNe":"Microscopy बाट stomata, trichomes र calcium oxalate crystals जस्ता विशेषता पहिचान गर्न सकिन्छ।"}'::json,true),
('dph-pharmacognosy-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',304,'{"question":"Which phytochemical group is associated with senna?","translation":"Senna सँग कुन phytochemical समूह सम्बन्धित छ?","options":["Anthraquinone glycosides","Quinoline alkaloids","Volatile oil rich in eugenol","Cardiac glycosides"],"correctIndex":0,"explanation":"Senna contains anthraquinone glycosides, especially sennosides.","explanationNe":"Senna मा anthraquinone glycosides, विशेषगरी sennosides, पाइन्छन्।"}'::json,true),
('dph-pharmacognosy-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',305,'{"question":"Which set of conditions is most suitable for storing dried crude drugs?","translation":"सुकाइएको crude drug भण्डारण गर्न कुन अवस्था सबैभन्दा उपयुक्त हुन्छ?","options":["Clean, dry, labelled and pest-protected container","Open wet container in sunlight","Unlabelled mixed sacks","Humid place near strong-smelling chemicals"],"correctIndex":0,"explanation":"Clean, dry and labelled storage reduces moisture damage, infestation and mix-ups.","explanationNe":"सफा, सुक्खा र label गरिएको भण्डारणले चिस्यानबाट हुने क्षति, कीराको संक्रमण र मिसावट घटाउँछ।"}'::json,true)
